    def get_dkg_nodes(self, wallet_id: str) -> dict:
        """读取 DKG 节点健康表：已配置 200 返回 Q，未配置 404。

        返回的是**生效**健康表：最后一条 node_state 快照，再折叠其后已
        提交 node_rejoined 事件把对应节点置 up（rejoin 不另写快照）。
        损坏/矛盾事件 fail-closed（由 HTTP 边界转 503）。钱包不存在
        404。"""
